    // Active DFI gear = log2(active DFI rate). DFI_RATE is the compile-time MAX
    // rate that sizes every bus; gear_i selects how many of those phases are
    // active. active_rate = 1 << gear_i. At gear_i = log2(DFI_RATE) (board /
    // default) the mask is all-ones and the DFI en outputs are UNCHANGED.
    input  logic [1:0]                 gear_i,
    // Runtime sub-DFI-word framing (from the bl+gear CSRs; <= compile MAX).
    // n_subcmd_i = active DRAM commands per DFI word; sub_col_stride_i = active
    // device-word column stride; sub_phase_stride_i = active DFI-phase stride
    // (= active bl_pumice) between the packed sub-bursts. Board/default => MAX.
    input  logic [SUBW_MAX-1:0]        n_subcmd_i,
    input  logic [COL_WIDTH-1:0]       sub_col_stride_i,
    input  logic [PHW-1:0]             sub_phase_stride_i,

    // DFI command bus
    output logic [DFI_ADDR_BUS_W-1:0]  dfi_address_o,
    output logic [DFI_BANK_BUS_W-1:0]  dfi_bank_o,
    output logic [DFI_CTRL_BUS_W-1:0]  dfi_cas_n_o,
    output logic [DFI_CTRL_BUS_W-1:0]  dfi_ras_n_o,
    output logic [DFI_CTRL_BUS_W-1:0]  dfi_we_n_o,
    output logic [DFI_CS_BUS_W-1:0]    dfi_cs_n_o,
    output logic [DFI_CS_BUS_W-1:0]    dfi_odt_o,
    // DFI write data
    output logic [DFI_DATA_WIDTH-1:0]  dfi_wrdata_o,
    output logic [DFI_EN_WIDTH-1:0]    dfi_wrdata_en_o,
    output logic [DFI_STRB_WIDTH-1:0]  dfi_wrdata_mask_o,
    // DFI read data
    output logic [DFI_EN_WIDTH-1:0]    dfi_rddata_en_o,
    input  logic [DFI_DATA_WIDTH-1:0]  dfi_rddata_i,
    input  logic [DFI_VALID_WIDTH-1:0] dfi_rddata_valid_i,
    // DFI init handshake (to/from PHY)
    output logic                       dfi_init_start_o,
    input  logic                       dfi_init_complete_i,

    // ---- DDR3 write-leveling handshake (DFI v3.1, per CS) ----
    // It crosses HERE, with the command path, because this module owns the one
    // ctl_clk/dfi_clk boundary in the design. scoria_wrlvl_ifc runs on ctl_clk
    // and the PHY samples these pins on dfi_clk; wiring them from the scheduler
    // straight to the top's pin bus would have been an UNSYNCHRONIZED crossing,
    // and no lint pass reports that -- it reports nothing at all.
    //
    // The two directions need different primitives. The request/mode/ack/result
    // signals are slow levels, so a flop chain is enough. wl_strobe_i is a
    // ONE-CYCLE pulse and a flop chain would either duplicate or swallow it
    // depending on the clock ratio, so it goes through sync_pulse's toggle
    // handshake instead.
    input  logic [NUM_CS-1:0]          wl_req_cs_n_i,    // ctl_clk, level
    input  logic [NUM_CS-1:0]          wl_wrlvl_cs_n_i,  // ctl_clk, level
    input  logic                       wl_strobe_i,      // ctl_clk, 1-cycle pulse
    output logic [NUM_CS-1:0]          wl_ack_cs_n_o,    // ctl_clk, level
    output logic                       wl_prime_dq_o,    // ctl_clk, level

    output logic [NUM_CS-1:0]          dfi_phylvl_req_cs_n_o,
    input  logic [NUM_CS-1:0]          dfi_phylvl_ack_cs_n_i,
    output logic [NUM_CS-1:0]          dfi_phy_wrlvl_cs_n_o,
    output logic                       dfi_wrlvl_strobe_o,
    input  logic                       dfi_prime_dq_i
);

    // ---- CDC dfi-side nets ----
    logic               pcmd_valid, pcmd_ready;  logic [CMD_DW-1:0] pcmd_data;
    logic               pwd_valid,  pwd_ready;   logic [WD_DW-1:0]  pwd_data;
    logic               prd_valid,  prd_ready;   logic [RD_DW-1:0]  prd_data;
    logic               pinit_start;

    // ---- fire strobes ----
    logic               w_wr_fire, w_rd_fire, w_rd_op_ready;
    logic               w_wr_staged, w_wr_accept;
    logic [RKW-1:0]     w_fire_rank;

    // ---- active-gear phase mask ------------------------------------------
    // active_rate = 1 << gear_i (number of low DFI phases that are active).
    // Sized to hold DFI_RATE. When active_rate == DFI_RATE (gear_i =
    // log2(DFI_RATE), the board/default), w_phase_active is all-ones and the
    // en outputs below are bit-identical to the un-masked fub outputs.
    localparam int RATEW = $clog2(DFI_RATE) + 1;
    logic [RATEW-1:0]        w_active_rate;
    assign w_active_rate = (RATEW'(1) << gear_i);

    logic [DFI_EN_WIDTH-1:0] w_phase_active;
    always_comb begin
        for (int p = 0; p < DFI_EN_WIDTH; p++)
            w_phase_active[p] = (RATEW'(p) < w_active_rate);
    end

    // fub-driven (un-masked) DFI en; gated to the active phases at the output.
    logic [DFI_EN_WIDTH-1:0] w_dfi_wrdata_en, w_dfi_rddata_en;
    assign dfi_wrdata_en_o = w_dfi_wrdata_en & w_phase_active;
    assign dfi_rddata_en_o = w_dfi_rddata_en & w_phase_active;

    // ---- unpack wrdata / pack rddata ----
    logic                      w_wd_last;
    logic [DFI_STRB_WIDTH-1:0] w_wd_strb;
    logic [DFI_DATA_WIDTH-1:0] w_wd_data;
    assign {w_wd_last, w_wd_strb, w_wd_data} = pwd_data;

    logic                      w_rd_last;
    logic [1:0]                w_rd_resp;
    logic [DFI_DATA_WIDTH-1:0] w_rd_data;
    assign prd_data = {w_rd_last, w_rd_resp, w_rd_data};

    // ======================================================================
    // Single CDC (async gaxi FIFOs only)
    // ======================================================================
    mc_dfi_cdc #(
        .CMD_DW      (CMD_DW),
        .WD_DW       (WD_DW),
        .RD_DW       (RD_DW),
        .CMD_DEPTH   (CMD_FIFO_DEPTH),
        .WD_DEPTH    (WD_FIFO_DEPTH),
        .RD_DEPTH    (RD_FIFO_DEPTH),
        .N_FLOP_CROSS(N_FLOP_CROSS),
        .USE_JOHNSON (USE_JOHNSON),
        .DFI_CDC_EN  (DFI_CDC_EN)
    ) u_cdc (
        .ctl_clk         (ctl_clk),
        .ctl_rstn        (ctl_rstn),
        .cmd_valid_i     (cmd_valid_i),
        .cmd_ready_o     (cmd_ready_o),
        .cmd_data_i      (cmd_data_i),
        .wd_valid_i      (wd_valid_i),
        .wd_ready_o      (wd_ready_o),
        .wd_data_i       (wd_data_i),
        .wd_last_i       (wd_data_i[WD_DW-1]),   // {last, strb, data}: last is the MSB
        .init_start_i    (init_start_i),
        .rd_valid_o      (rd_valid_o),
        .rd_ready_i      (rd_ready_i),
        .rd_data_o       (rd_data_o),
        .init_complete_o (init_complete_o),
        .dfi_clk         (dfi_clk),
        .dfi_rstn        (dfi_rstn),
        .pcmd_valid_o    (pcmd_valid),
        .pcmd_ready_i    (pcmd_ready),
        .pcmd_data_o     (pcmd_data),
        .pwd_valid_o     (pwd_valid),
        .pwd_ready_i     (pwd_ready),
        .pwd_data_o      (pwd_data),
        .pwr_staged_valid_o(w_wr_staged),
        .pwr_staged_pop_i(w_wr_accept),
        .pinit_start_o   (pinit_start),
        .prd_valid_i     (prd_valid),
        .prd_ready_o     (prd_ready),
        .prd_data_i      (prd_data),
        .pinit_complete_i(dfi_init_complete_i)
    );

    assign dfi_init_start_o = pinit_start;

    // ======================================================================
    // Command path (dfi_clk): cmd FIFO -> DFI command bus + fire strobes
    // ======================================================================
    mc_dfi_3p1_cmd_path #(
        .NUM_RANKS       (NUM_RANKS),
        .NUM_BANKS       (NUM_BANKS),
        .ROW_WIDTH       (ROW_WIDTH),
        .COL_WIDTH       (COL_WIDTH),
        .DFI_RATE        (DFI_RATE),
        .N_SUBCMD        (N_SUBCMD),
        .SUB_COL_STRIDE  (SUB_COL_STRIDE),
        .SUB_PHASE_STRIDE(SUB_PHASE_STRIDE),
        .DFI_ADDR_WIDTH  (DFI_ADDR_WIDTH),
        .DFI_BANK_WIDTH  (DFI_BANK_WIDTH),
        .DFI_CTRL_WIDTH  (DFI_CTRL_WIDTH),
        .DFI_CS_WIDTH    (DFI_CS_WIDTH),
        .CMD_HISTORY_EN  (CMD_HISTORY_EN),
        .HIST_T_RCD      (HIST_T_RCD),
        .HIST_T_RP       (HIST_T_RP),
        .HIST_T_RAS      (HIST_T_RAS),
        .HIST_T_RFC      (HIST_T_RFC),
        .HIST_T_WTR      (HIST_T_WTR),
        .HIST_T_RTW      (HIST_T_RTW)
    ) u_cmd (
        .dfi_clk           (dfi_clk),
        .dfi_rstn          (dfi_rstn),
        .memtype_i         (memtype_i),
        .rd_phase_i        (rd_phase_i),
        .wr_phase_i        (wr_phase_i),
        .n_subcmd_i        (n_subcmd_i),
        .sub_col_stride_i  (sub_col_stride_i),
        .sub_phase_stride_i(sub_phase_stride_i),
        .cmd_valid_i       (pcmd_valid),
        .cmd_ready_o       (pcmd_ready),
        .cmd_data_i        (pcmd_data),
        .dfi_address_o     (dfi_address_o),
        .dfi_bank_o        (dfi_bank_o),
        .dfi_cas_n_o       (dfi_cas_n_o),
        .dfi_ras_n_o       (dfi_ras_n_o),
        .dfi_we_n_o        (dfi_we_n_o),
        .dfi_cs_n_o        (dfi_cs_n_o),
        .dfi_odt_o         (dfi_odt_o),
        .wr_fire_o         (w_wr_fire),
        .rd_fire_o         (w_rd_fire),
        .fire_rank_o       (w_fire_rank),
        .rd_op_ready_i     (w_rd_op_ready),
        .wr_op_ready_i     (w_wr_staged),
        .wr_accept_o       (w_wr_accept)
    );

    // ======================================================================
    // Write serializer (dfi_clk): wrdata FIFO -> dfi_wrdata at t_phy_wrlat
    // ======================================================================
    mc_dfi_wr_serializer #(
        .DFI_DATA_WIDTH(DFI_DATA_WIDTH),
        .DFI_RATE      (DFI_RATE)
    ) u_wr (
        .dfi_clk          (dfi_clk),
        .dfi_rstn         (dfi_rstn),
        .t_phy_wrlat_i    (t_phy_wrlat_i),
        .wr_fire_i        (w_wr_fire),
        .wd_valid_i       (pwd_valid),
        .wd_ready_o       (pwd_ready),
        .wd_data_i        (w_wd_data),
        .wd_strb_i        (w_wd_strb),
        .wd_last_i        (w_wd_last),
        .db_wr_dbi_en_i   (1'b0),
        .wd_dbi_i         ('0),
        .dfi_wrdata_o     (dfi_wrdata_o),
        .dfi_wrdata_en_o  (w_dfi_wrdata_en),
        .dfi_wrdata_mask_o(dfi_wrdata_mask_o)
    );

    // ======================================================================
    // Read aligner (dfi_clk): dfi_rddata -> rddata FIFO at t_rddata_en
    // ======================================================================
    mc_dfi_rd_aligner #(
        .DFI_DATA_WIDTH (DFI_DATA_WIDTH),
        .DFI_RATE       (DFI_RATE),
        .DFI_VALID_WIDTH(DFI_VALID_WIDTH),
        .BL_WORDS       (BL_WORDS),
        .EN_CYC         (RD_EN_CYC),
        .MAX_OUTSTANDING(RD_MAX_OUTSTANDING),
        .HAS_CAL_CAPTURE(0),
        .HAS_DBI        (0)
    ) u_rd (
        .dfi_clk           (dfi_clk),
        .dfi_rstn          (dfi_rstn),
        .t_rddata_en_i     (t_rddata_en_i),
        .op_valid_i        (w_rd_fire),
        .op_ready_o        (w_rd_op_ready),
        .dfi_rddata_en_o   (w_dfi_rddata_en),
        .dfi_rddata_i      (dfi_rddata_i),
        .dfi_rddata_valid_i(dfi_rddata_valid_i),
        .rd_valid_o        (prd_valid),
        .rd_ready_i        (prd_ready),
        .rd_data_o         (w_rd_data),
        // Exported by mc_dfi_2p1_plane to the core's read-return window (e95df1694);
        // this plane does not carry that window yet, so the pin is tied off here.
        .rd_ret_busy_o     (),
        .rd_resp_o         (w_rd_resp),
        .rd_last_o         (w_rd_last),
        .rd_dbi_en_i       (1'b0),
        .dfi_rddata_dbi_i  ('0),
        .rd_dbi_o          (),
        .cal_expect_i      (1'b0),
        .cal_data_o        (),
        .cal_valid_o       ()
    );

    wire unused = &{1'b0, w_fire_rank, 1'b0};

    // ========================================================================
    // Write-leveling CDC
    // ========================================================================
    // Every level is synchronized in its ACTIVE-HIGH form and inverted at the
    // far side. glitch_free_n_dff_arn (under cdc_synchronizer) resets its chain
    // to zero, so feeding it an active-low _n signal directly would present
    // "asserted" for the first few destination cycles out of reset -- a
    // spurious leveling request into the PHY before the controller has asked
    // for anything.
    logic [NUM_CS-1:0] w_wl_req_h,   w_wl_req_h_sync;
    logic [NUM_CS-1:0] w_wl_mode_h,  w_wl_mode_h_sync;
    logic [NUM_CS-1:0] w_wl_ack_h,   w_wl_ack_h_sync;
    logic              w_wl_dq_sync;

    assign w_wl_req_h  = ~wl_req_cs_n_i;
    assign w_wl_mode_h = ~wl_wrlvl_cs_n_i;
    assign w_wl_ack_h  = ~dfi_phylvl_ack_cs_n_i;

    // ctl_clk -> dfi_clk
    cdc_synchronizer #(.WIDTH(NUM_CS), .FLOP_COUNT(3)) u_wl_req_sync (
        .clk      (dfi_clk),
        .rst_n    (dfi_rstn),
        .async_in (w_wl_req_h),
        .sync_out (w_wl_req_h_sync)
    );
    cdc_synchronizer #(.WIDTH(NUM_CS), .FLOP_COUNT(3)) u_wl_mode_sync (
        .clk      (dfi_clk),
        .rst_n    (dfi_rstn),
        .async_in (w_wl_mode_h),
        .sync_out (w_wl_mode_h_sync)
    );
    assign dfi_phylvl_req_cs_n_o = ~w_wl_req_h_sync;
    assign dfi_phy_wrlvl_cs_n_o  = ~w_wl_mode_h_sync;

    // dfi_clk -> ctl_clk. prime_dq is a data BIT, but it is a level that the
    // PHY holds steady from tWLO until the next strobe, so a flop chain is the
    // right primitive -- it is not a bus whose bits must agree on one cycle.
    cdc_synchronizer #(.WIDTH(NUM_CS), .FLOP_COUNT(3)) u_wl_ack_sync (
        .clk      (ctl_clk),
        .rst_n    (ctl_rstn),
        .async_in (w_wl_ack_h),
        .sync_out (w_wl_ack_h_sync)
    );
    cdc_synchronizer #(.WIDTH(1), .FLOP_COUNT(3)) u_wl_dq_sync (
        .clk      (ctl_clk),
        .rst_n    (ctl_rstn),
        .async_in (dfi_prime_dq_i),
        .sync_out (w_wl_dq_sync)
    );
    assign wl_ack_cs_n_o = ~w_wl_ack_h_sync;
    assign wl_prime_dq_o = w_wl_dq_sync;

    // The strobe: ONE ctl_clk pulse in, ONE dfi_clk pulse out. sync_pulse
    // crosses a toggle and edge-detects on the far side, which is what makes
    // the count survive the ratio. scoria_wrlvl_ifc then waits tWLO before
    // sampling, and tWLO is orders of magnitude longer than this crossing, so
    // the synchronizer latency does not eat into the result window.
    sync_pulse #(.SYNC_STAGES(3)) u_wl_strobe_sync (
        .i_src_clk   (ctl_clk),
        .i_src_rst_n (ctl_rstn),
        .i_pulse     (wl_strobe_i),
        .i_dst_clk   (dfi_clk),
        .i_dst_rst_n (dfi_rstn),
        .o_pulse     (dfi_wrlvl_strobe_o)
    );

endmodule : mc_dfi_3p1_plane
